import sqlite3
import json
import os
import random

# Load shop configuration
with open("config.json", "r", encoding="utf-8") as f:
    config = json.load(f)

store_name = config.get("store_name")
owner_name = config.get("owner_name")
store_address = config.get("store_address")
store_contact = config.get("store_contact")

# Delete old messages file if exists
if os.path.exists("messages.json"):
    os.remove("messages.json")

# Database connection
DATABASE = "database.db"
#query = """
#    SELECT date, customer_name, address, phone_number, shopping_details,
#           total_amount, paid_amount, remaining_credit
#    FROM sales
#    WHERE credit = 1
#"""

query = """
    SELECT date, customer_name, address, phone_number, shopping_details,
           total_amount, paid_amount, remaining_credit
    FROM sales
    WHERE phone_number = 9973499190
"""

with sqlite3.connect(DATABASE) as conn:
    cursor = conn.cursor()
    cursor.execute(query)
    rows = cursor.fetchall()

