def format_shopping(shopping_details):
    items = json.loads(shopping_details)
    return ", ".join([
        f"{i['article']} ({i['type']}" + (f", {i['carat']})" if i.get('carat') else ")")
        for i in items
    ])

# Generate messages
messages = []
for row in rows:
    date, name, address, phone, shopping_json, total, paid, due = row
    phone = f"+91{phone.strip()}"
    shopping_summary = format_shopping(shopping_json)
    template = random.choice(templates)

    message = template.format(
        name=name,
        date=date,
        total=int(total),
        paid=int(paid),
        due=int(due),
        shopping=shopping_summary,
        store_name=store_name,
        owner_name=owner_name,
        store_address=store_address,
        store_contact=store_contact
    )

    messages.append({
        "number": phone,
        "message": message
    })

# Save as JSON
with open("messages.json", "w", encoding="utf-8") as f:
    json.dump(messages, f, ensure_ascii=False, indent=2)

print(f"✅ {len(messages)} messages prepared in messages.json")
